--
-- Name: protect_admin_settings_permission_catalog(); Type: FUNCTION; Schema: auth; Owner: gilbom_flyway
--

CREATE FUNCTION auth.protect_admin_settings_permission_catalog() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'auth'
    AS $$
BEGIN
    IF OLD.permission_code = 'ADMIN_SETTINGS_MANAGE' THEN
        IF TG_OP = 'DELETE' THEN
            RAISE EXCEPTION 'ADMIN_SETTINGS_MANAGE permission is protected'
                USING ERRCODE = '42501';
        END IF;

        IF NEW.permission_code <> 'ADMIN_SETTINGS_MANAGE'
           OR NEW.is_system = FALSE
           OR NEW.is_active = FALSE THEN
            RAISE EXCEPTION 'ADMIN_SETTINGS_MANAGE permission is protected'
                USING ERRCODE = '42501';
        END IF;
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION auth.protect_admin_settings_permission_catalog() OWNER TO gilbom_flyway;

--
-- Name: protect_last_admin_on_user_change(); Type: FUNCTION; Schema: auth; Owner: gilbom_flyway
--

CREATE FUNCTION auth.protect_last_admin_on_user_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'auth'
    AS $$
BEGIN
    IF (
        NEW.account_status <> 'ACTIVE'
        OR NEW.is_active = FALSE
        OR NEW.deleted_at IS NOT NULL
    ) THEN
        PERFORM auth.assert_last_active_admin_preserved(OLD.user_id);
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION auth.protect_last_admin_on_user_change() OWNER TO gilbom_flyway;

--
-- Name: protect_last_admin_on_user_role_change(); Type: FUNCTION; Schema: auth; Owner: gilbom_flyway
--

CREATE FUNCTION auth.protect_last_admin_on_user_role_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'auth'
    AS $$
DECLARE
    old_is_system_admin_role BOOLEAN;
BEGIN
    SELECT (
        role.role_code = 'ADMIN'
        AND role.is_system = TRUE
    )
      INTO old_is_system_admin_role
      FROM auth.role role
     WHERE role.role_id = OLD.role_id;

    IF OLD.is_active = TRUE AND old_is_system_admin_role THEN
        IF TG_OP = 'DELETE' THEN
            PERFORM auth.assert_last_active_admin_preserved(OLD.user_id);
            RETURN OLD;
        END IF;

        IF NEW.is_active = FALSE
           OR NEW.user_id <> OLD.user_id
           OR NEW.role_id <> OLD.role_id THEN
            PERFORM auth.assert_last_active_admin_preserved(OLD.user_id);
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION auth.protect_last_admin_on_user_role_change() OWNER TO gilbom_flyway;

