--
-- Name: record_authorization_session_revocation(character varying, uuid, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: auth; Owner: gilbom_flyway
--

CREATE FUNCTION auth.record_authorization_session_revocation(target_type_code character varying, target_entity_id uuid, revocation_source character varying, trigger_name character varying, trigger_operation character varying, deleted_session_count integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'audit'
    AS $_$
BEGIN
    IF deleted_session_count <= 0 THEN
        RETURN;
    END IF;

    IF target_type_code NOT IN ('USER', 'ROLE', 'PERMISSION')
       OR revocation_source NOT IN (
           'USER_ROLE',
           'ROLE_PERMISSION',
           'ROLE_LIFECYCLE',
           'PERMISSION_LIFECYCLE',
           'USER_PERMISSION_OVERRIDE',
           'USER_ROBOT_ASSIGNMENT',
           'ACCOUNT_LIFECYCLE'
       )
       OR trigger_name !~ '^tr_[a-z0-9_]{1,76}$'
       OR trigger_operation NOT IN ('INSERT', 'UPDATE', 'DELETE') THEN
        RAISE EXCEPTION 'invalid authorization session revocation audit input'
            USING ERRCODE = '22023';
    END IF;

    -- PostgreSQL 운영 로그에서도 idle 만료와 DB trigger 폐기를 즉시 구분할 수
    -- 있게 하되 Session ID나 요청 식별자는 남기지 않는다.
    RAISE LOG 'session revoked by trigger: source=%, trigger=%, op=%, target_type=%, target_id=%, sessions=%',
        revocation_source,
        trigger_name,
        trigger_operation,
        target_type_code,
        target_entity_id,
        deleted_session_count;

        request_id,
        actor_user_id,
        actor_type,
        action_type,
        target_type,
        target_id,
        before_value,
        after_value,
        reason,
        result,
        ip_address,
        user_agent
    ) VALUES (
        NULL,
        NULL,
        'SYSTEM',
        'AUTH_SESSION_REVOKED',
        target_type_code,
        target_entity_id,
        NULL,
        jsonb_build_object(
            'deletedSessionCount', deleted_session_count,
            'source', revocation_source,
            'trigger', trigger_name,
            'operation', trigger_operation
        ),
        'AUTHORIZATION_CHANGE:' || revocation_source,
        'SUCCESS',
        NULL,
        NULL
    );
END;
$_$;


ALTER FUNCTION auth.record_authorization_session_revocation(target_type_code character varying, target_entity_id uuid, revocation_source character varying, trigger_name character varying, trigger_operation character varying, deleted_session_count integer) OWNER TO gilbom_flyway;

--
-- Name: FUNCTION record_authorization_session_revocation(target_type_code character varying, target_entity_id uuid, revocation_source character varying, trigger_name character varying, trigger_operation character varying, deleted_session_count integer); Type: COMMENT; Schema: auth; Owner: gilbom_flyway
--

COMMENT ON FUNCTION auth.record_authorization_session_revocation(target_type_code character varying, target_entity_id uuid, revocation_source character varying, trigger_name character varying, trigger_operation character varying, deleted_session_count integer) IS '권한 변경 DB trigger가 실제 session을 삭제했을 때 원인·trigger·DML·건수를 SYSTEM 감사 로그로 기록';


--
-- Name: reject_totp_time_step_regression(); Type: FUNCTION; Schema: auth; Owner: gilbom_flyway
--

CREATE FUNCTION auth.reject_totp_time_step_regression() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.last_successful_totp_time_step IS NOT NULL
       AND NEW.last_successful_totp_time_step
           IS DISTINCT FROM OLD.last_successful_totp_time_step
       AND (
           NEW.last_successful_totp_time_step IS NULL
           OR NEW.last_successful_totp_time_step
               <= OLD.last_successful_totp_time_step
       ) THEN
        RAISE EXCEPTION 'TOTP time-step cannot move backwards'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION auth.reject_totp_time_step_regression() OWNER TO gilbom_flyway;

--
-- Name: revoke_permission_authorization_sessions(uuid); Type: FUNCTION; Schema: auth; Owner: gilbom_flyway
--

CREATE FUNCTION auth.revoke_permission_authorization_sessions(target_permission_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'auth', 'session_store'
    AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM session_store.spring_session session
    USING session_store.session_security_state security_state
    WHERE security_state.session_primary_id = session.primary_id
      AND (
          EXISTS (
              SELECT 1
              FROM auth.role_permission role_permission
              JOIN auth.user_role user_role
                ON user_role.role_id = role_permission.role_id
              WHERE role_permission.permission_id =
                    target_permission_id
                AND role_permission.is_active = TRUE
                AND user_role.is_active = TRUE
                AND user_role.user_id = security_state.user_id
          )
          OR EXISTS (
              SELECT 1
              FROM auth.user_permission_override
                   permission_override
              WHERE permission_override.permission_id =
                    target_permission_id
                AND permission_override.is_active = TRUE
                AND permission_override.user_id =
                    security_state.user_id
          )
      );

    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;


ALTER FUNCTION auth.revoke_permission_authorization_sessions(target_permission_id uuid) OWNER TO gilbom_flyway;

--
-- Name: revoke_role_authorization_sessions(uuid); Type: FUNCTION; Schema: auth; Owner: gilbom_flyway
--

CREATE FUNCTION auth.revoke_role_authorization_sessions(target_role_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'auth', 'session_store'
    AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM session_store.spring_session session
    USING session_store.session_security_state security_state
    WHERE security_state.session_primary_id = session.primary_id
      AND EXISTS (
          SELECT 1
          FROM auth.user_role user_role
          WHERE user_role.user_id = security_state.user_id
            AND user_role.role_id = target_role_id
            AND user_role.is_active = TRUE
      );

    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;


