--
-- Name: revoke_sessions_on_user_scope_change(); Type: FUNCTION; Schema: auth; Owner: gilbom_flyway
--

CREATE FUNCTION auth.revoke_sessions_on_user_scope_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'auth'
    AS $$
DECLARE
    deleted_count INTEGER;
    source_code VARCHAR;
BEGIN
    source_code := CASE TG_TABLE_NAME
        WHEN 'user_permission_override' THEN 'USER_PERMISSION_OVERRIDE'
        WHEN 'user_robot_assignment' THEN 'USER_ROBOT_ASSIGNMENT'
        ELSE NULL
    END;

    IF source_code IS NULL THEN
        RAISE EXCEPTION 'unsupported user scope revocation table: %',
            TG_TABLE_NAME
            USING ERRCODE = '22023';
    END IF;

    IF TG_OP = 'DELETE' THEN
        deleted_count := auth.revoke_user_authorization_sessions(OLD.user_id);
        PERFORM auth.record_authorization_session_revocation(
            'USER', OLD.user_id, source_code,
            TG_NAME::VARCHAR, TG_OP::VARCHAR, deleted_count
        );
        RETURN OLD;
    END IF;

    deleted_count := auth.revoke_user_authorization_sessions(NEW.user_id);
    PERFORM auth.record_authorization_session_revocation(
        'USER', NEW.user_id, source_code,
        TG_NAME::VARCHAR, TG_OP::VARCHAR, deleted_count
    );

    IF TG_OP = 'UPDATE' AND OLD.user_id <> NEW.user_id THEN
        deleted_count := auth.revoke_user_authorization_sessions(OLD.user_id);
        PERFORM auth.record_authorization_session_revocation(
            'USER', OLD.user_id, source_code,
            TG_NAME::VARCHAR, TG_OP::VARCHAR, deleted_count
        );
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION auth.revoke_sessions_on_user_scope_change() OWNER TO gilbom_flyway;

--
-- Name: revoke_user_authorization_sessions(uuid); Type: FUNCTION; Schema: auth; Owner: gilbom_flyway
--

CREATE FUNCTION auth.revoke_user_authorization_sessions(target_user_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'auth', 'session_store'
    AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM session_store.spring_session session
    USING session_store.session_security_state security_state
    WHERE security_state.session_primary_id = session.primary_id
      AND security_state.user_id = target_user_id;

    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;


ALTER FUNCTION auth.revoke_user_authorization_sessions(target_user_id uuid) OWNER TO gilbom_flyway;

