--
-- Name: require_report_version_pointer(); Type: FUNCTION; Schema: report; Owner: gilbom_flyway
--

CREATE FUNCTION report.require_report_version_pointer() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    header_version_no INTEGER;
BEGIN
    SELECT current_version_no
    INTO header_version_no
    FROM report.anomaly_report
    WHERE report_id = NEW.report_id;

    IF header_version_no IS DISTINCT FROM NEW.version_no THEN
        RAISE EXCEPTION 'inserted report version must become current'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


