--
-- Name: enforce_created_mission_delete(); Type: FUNCTION; Schema: robot; Owner: gilbom_flyway
--

CREATE FUNCTION robot.enforce_created_mission_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'robot'
    AS $$
BEGIN
    IF OLD.status <> 'CREATED'
            OR OLD.started_at IS NOT NULL
            OR OLD.ended_at IS NOT NULL
            OR OLD.progress_percent <> 0 THEN
        RAISE EXCEPTION 'only untouched CREATED mission can be deleted'
            USING ERRCODE = '55000';
    END IF;
    RETURN OLD;
END;
$$;


