-- Name: FUNCTION enforce_created_mission_delete(); Type: COMMENT; Schema: robot; Owner: gilbom_flyway
--

COMMENT ON FUNCTION robot.enforce_created_mission_delete() IS '시작·진행 이력이 없는 CREATED Mission만 물리 삭제하도록 강제';


--
-- Name: enforce_mission_status_transition(); Type: FUNCTION; Schema: robot; Owner: gilbom_flyway
--

CREATE FUNCTION robot.enforce_mission_status_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'robot'
    AS $$
BEGIN
    IF OLD.status = NEW.status THEN
        RETURN NEW;
    END IF;

    IF (OLD.status = 'CREATED'
            AND NEW.status IN ('READY', 'RUNNING', 'CANCELLED'))
        OR (OLD.status = 'READY'
            AND NEW.status IN ('RUNNING', 'CANCELLED', 'FAILED'))
        OR (OLD.status = 'RUNNING'
            AND NEW.status IN (
                'PAUSED',
                'COMPLETED',
                'CANCELLED',
                'FAILED'
            ))
        OR (OLD.status = 'PAUSED'
            AND NEW.status IN ('RUNNING', 'CANCELLED', 'FAILED'))
    THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION
        'illegal mission status transition: % -> %',
        OLD.status,
        NEW.status
        USING ERRCODE = '23514';
END;
$$;


ALTER FUNCTION robot.enforce_mission_status_transition() OWNER TO gilbom_flyway;

--
-- Name: reject_mission_status_history_mutation(); Type: FUNCTION; Schema: robot; Owner: gilbom_flyway
--

CREATE FUNCTION robot.reject_mission_status_history_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'robot'
    AS $$
BEGIN
    IF TG_OP = 'DELETE'
            AND OLD.before_status IS NULL
            AND OLD.after_status = 'CREATED'
            AND OLD.source_event_id IS NULL
            AND EXISTS (
                SELECT 1
                FROM robot.mission mission
                WHERE mission.mission_id = OLD.mission_id
                  AND mission.status = 'CREATED'
                  AND mission.started_at IS NULL
                  AND mission.ended_at IS NULL
                  AND mission.progress_percent = 0
            )
            AND NOT EXISTS (
                SELECT 1
                FROM robot.mission_status_history history
                WHERE history.mission_id = OLD.mission_id
                  AND history.history_id <> OLD.history_id
            ) THEN
        RETURN OLD;
    END IF;

    RAISE EXCEPTION 'mission_status_history is append-only'
        USING ERRCODE = '55000';
END;
$$;


ALTER FUNCTION robot.reject_mission_status_history_mutation() OWNER TO gilbom_flyway;

