SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: audit_log; Type: TABLE; Schema: audit; Owner: gilbom_flyway
--

CREATE TABLE audit.audit_log (
    audit_id bigint NOT NULL,
    request_id uuid,
    actor_user_id uuid,
    actor_type character varying(20) NOT NULL,
    action_type character varying(80) NOT NULL,
    target_type character varying(50) NOT NULL,
    target_id uuid,
    before_value jsonb,
    after_value jsonb,
    reason character varying(1000),
    result character varying(20) NOT NULL,
    ip_address inet,
    user_agent character varying(500),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_audit_action_type CHECK (((action_type)::text ~ '^[A-Z][A-Z0-9_]{2,79}$'::text)),
    CONSTRAINT ck_audit_actor CHECK ((((actor_type)::text = 'USER'::text) OR (((actor_type)::text = ANY ((ARRAY['SYSTEM'::character varying, 'ROBOT'::character varying])::text[])) AND (actor_user_id IS NULL)))),
    CONSTRAINT ck_audit_actor_type CHECK (((actor_type)::text = ANY ((ARRAY['USER'::character varying, 'SYSTEM'::character varying, 'ROBOT'::character varying])::text[]))),
    CONSTRAINT ck_audit_after_value CHECK (((after_value IS NULL) OR (jsonb_typeof(after_value) = 'object'::text))),
    CONSTRAINT ck_audit_before_value CHECK (((before_value IS NULL) OR (jsonb_typeof(before_value) = 'object'::text))),
    CONSTRAINT ck_audit_result CHECK (((result)::text = ANY ((ARRAY['SUCCESS'::character varying, 'FAILURE'::character varying, 'DENIED'::character varying])::text[]))),
    CONSTRAINT ck_audit_target_type CHECK (((target_type)::text ~ '^[A-Z][A-Z0-9_]{1,49}$'::text)),
    CONSTRAINT ck_audit_user_agent CHECK (((user_agent IS NULL) OR ((user_agent)::text !~ '[[:cntrl:]]'::text)))
);


ALTER TABLE audit.audit_log OWNER TO gilbom_flyway;

--
-- Name: TABLE audit_log; Type: COMMENT; Schema: audit; Owner: gilbom_flyway
--

COMMENT ON TABLE audit.audit_log IS '인증·권한·업무 행위를 민감 인증정보 없이 추가 전용으로 보존하는 감사 로그';


