--
-- Name: admin_user; Type: TABLE; Schema: auth; Owner: gilbom_flyway
--

CREATE TABLE auth.admin_user (
    user_id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_code character varying(30) NOT NULL,
    legacy_username character varying(50),
    password_hash character varying(512) NOT NULL,
    display_name character varying(100) NOT NULL,
    email character varying(254) NOT NULL,
    department_name character varying(100),
    job_title character varying(100),
    office_name character varying(100),
    is_active boolean DEFAULT false NOT NULL,
    password_change_required boolean DEFAULT true NOT NULL,
    password_changed_at timestamp with time zone,
    last_login_at timestamp with time zone,
    deleted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    normalized_email character varying(254) GENERATED ALWAYS AS (lower((email)::text)) STORED NOT NULL,
    account_status character varying(24) DEFAULT 'PENDING_APPROVAL'::character varying NOT NULL,
    failed_login_count integer DEFAULT 0 NOT NULL,
    last_failed_login_at timestamp with time zone,
    locked_until timestamp with time zone,
    account_origin character varying(24) DEFAULT 'PUBLIC_REGISTRATION'::character varying NOT NULL,
    mfa_required boolean DEFAULT true NOT NULL,
    CONSTRAINT ck_admin_account_lifecycle CHECK (((((account_status)::text = 'PENDING_APPROVAL'::text) AND (is_active = false) AND (deleted_at IS NULL)) OR (((account_status)::text = 'ACTIVE'::text) AND (is_active = true) AND (deleted_at IS NULL)) OR (((account_status)::text = ANY ((ARRAY['DISABLED'::character varying, 'REJECTED'::character varying])::text[])) AND (is_active = false) AND (deleted_at IS NULL)) OR (((account_status)::text = 'DELETED'::text) AND (is_active = false) AND (deleted_at IS NOT NULL)))),
    CONSTRAINT ck_admin_account_origin CHECK (((account_origin)::text = ANY ((ARRAY['PUBLIC_REGISTRATION'::character varying, 'BOOTSTRAP'::character varying, 'ADMIN_CREATED'::character varying, 'MIGRATED'::character varying])::text[]))),
    CONSTRAINT ck_admin_account_status CHECK (((account_status)::text = ANY ((ARRAY['PENDING_APPROVAL'::character varying, 'ACTIVE'::character varying, 'DISABLED'::character varying, 'REJECTED'::character varying, 'DELETED'::character varying])::text[]))),
    CONSTRAINT ck_admin_display_name_not_blank CHECK ((((display_name)::text = btrim((display_name)::text)) AND ((display_name)::text <> ''::text))),
    CONSTRAINT ck_admin_email_not_blank CHECK ((((email)::text = btrim((email)::text)) AND ((email)::text <> ''::text))),
    CONSTRAINT ck_admin_legacy_username CHECK (((legacy_username IS NULL) OR (((legacy_username)::text = btrim((legacy_username)::text)) AND ((legacy_username)::text <> ''::text)))),
    CONSTRAINT ck_admin_login_failure_state CHECK (((((account_status)::text = 'ACTIVE'::text) AND (((failed_login_count = 0) AND (last_failed_login_at IS NULL) AND (locked_until IS NULL)) OR ((failed_login_count > 0) AND (last_failed_login_at IS NOT NULL) AND ((locked_until IS NULL) OR (locked_until > last_failed_login_at))))) OR (((account_status)::text <> 'ACTIVE'::text) AND (failed_login_count = 0) AND (last_failed_login_at IS NULL) AND (locked_until IS NULL)))),
    CONSTRAINT ck_admin_password_change_state CHECK (((password_change_required = true) OR (password_changed_at IS NOT NULL))),
    CONSTRAINT ck_admin_password_hash_argon2id CHECK (((password_hash)::text ~~ '{argon2}$argon2id$%'::text)),
    CONSTRAINT ck_admin_password_hash_not_blank CHECK ((btrim((password_hash)::text) <> ''::text)),
    CONSTRAINT ck_admin_single_consultant_mfa_exemption CHECK (((mfa_required = true) OR ((user_id = '39000000-0000-4000-8000-000000000001'::uuid) AND ((normalized_email)::text = 'consultant.manager@gilbom.test'::text) AND (password_change_required = false)))),
    CONSTRAINT ck_admin_temporary_login_lock_policy CHECK ((((failed_login_count >= 0) AND (failed_login_count <= 5)) AND (((locked_until IS NULL) AND ((failed_login_count >= 0) AND (failed_login_count <= 4))) OR ((locked_until IS NOT NULL) AND (failed_login_count = 5) AND (locked_until = (last_failed_login_at + '00:15:00'::interval)))))),
    CONSTRAINT ck_admin_timestamps CHECK ((updated_at >= created_at))
);


ALTER TABLE auth.admin_user OWNER TO gilbom_flyway;

