--
-- Name: authentication_rate_limit; Type: TABLE; Schema: auth; Owner: gilbom_flyway
--

CREATE TABLE auth.authentication_rate_limit (
    rate_limit_id uuid DEFAULT gen_random_uuid() NOT NULL,
    limit_type character varying(30) NOT NULL,
    subject_key_hash bytea NOT NULL,
    hash_key_version integer NOT NULL,
    window_started_at timestamp with time zone NOT NULL,
    last_attempt_at timestamp with time zone NOT NULL,
    request_count integer DEFAULT 0 NOT NULL,
    failure_count integer DEFAULT 0 NOT NULL,
    blocked_until timestamp with time zone,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_authentication_rate_limit_counts CHECK (((request_count >= 0) AND (failure_count >= 0) AND (failure_count <= request_count))),
    CONSTRAINT ck_authentication_rate_limit_hash CHECK (((octet_length(subject_key_hash) = 32) AND (hash_key_version > 0))),
    CONSTRAINT ck_authentication_rate_limit_timestamps CHECK ((updated_at >= created_at)),
    CONSTRAINT ck_authentication_rate_limit_type CHECK (((limit_type)::text = ANY ((ARRAY['ACCOUNT_PASSWORD_FAILURE'::character varying, 'ACCOUNT_MFA_FAILURE'::character varying, 'IP_AUTHENTICATION_REQUEST'::character varying, 'IP_CSRF_TOKEN_ISSUANCE'::character varying, 'IP_EMAIL_AVAILABILITY_REQUEST'::character varying, 'IP_PUBLIC_REGISTRATION_REQUEST'::character varying])::text[]))),
    CONSTRAINT ck_authentication_rate_limit_window CHECK (((last_attempt_at >= window_started_at) AND (expires_at > window_started_at) AND ((blocked_until IS NULL) OR (blocked_until >= last_attempt_at))))
);


ALTER TABLE auth.authentication_rate_limit OWNER TO gilbom_flyway;

--
-- Name: TABLE authentication_rate_limit; Type: COMMENT; Schema: auth; Owner: gilbom_flyway
--

COMMENT ON TABLE auth.authentication_rate_limit IS '비밀번호·MFA 계정 실패와 인증·CSRF 발급·중복 확인·회원가입 IP 요청의 HMAC Rate Limit bucket';


