--
-- Name: mfa_factor; Type: TABLE; Schema: auth; Owner: gilbom_flyway
--

CREATE TABLE auth.mfa_factor (
    factor_id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    factor_type character varying(20) DEFAULT 'TOTP'::character varying NOT NULL,
    factor_status character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    secret_ciphertext bytea NOT NULL,
    secret_nonce bytea NOT NULL,
    secret_key_version integer NOT NULL,
    encryption_algorithm character varying(30) DEFAULT 'AES-256-GCM'::character varying NOT NULL,
    last_successful_totp_time_step bigint,
    activated_at timestamp with time zone,
    last_used_at timestamp with time zone,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_mfa_factor_algorithm CHECK (((encryption_algorithm)::text = 'AES-256-GCM'::text)),
    CONSTRAINT ck_mfa_factor_ciphertext CHECK ((octet_length(secret_ciphertext) >= 17)),
    CONSTRAINT ck_mfa_factor_key_version CHECK ((secret_key_version > 0)),
    CONSTRAINT ck_mfa_factor_lifecycle CHECK (((((factor_status)::text = 'PENDING'::text) AND (activated_at IS NULL) AND (revoked_at IS NULL)) OR (((factor_status)::text = 'ACTIVE'::text) AND (activated_at IS NOT NULL) AND (revoked_at IS NULL)) OR (((factor_status)::text = 'REVOKED'::text) AND (revoked_at IS NOT NULL)))),
    CONSTRAINT ck_mfa_factor_nonce CHECK ((octet_length(secret_nonce) = 12)),
    CONSTRAINT ck_mfa_factor_status CHECK (((factor_status)::text = ANY ((ARRAY['PENDING'::character varying, 'ACTIVE'::character varying, 'REVOKED'::character varying])::text[]))),
    CONSTRAINT ck_mfa_factor_time_step CHECK (((last_successful_totp_time_step IS NULL) OR (last_successful_totp_time_step >= 0))),
    CONSTRAINT ck_mfa_factor_type CHECK (((factor_type)::text = 'TOTP'::text))
);


