-- Name: user_permission_override; Type: TABLE; Schema: auth; Owner: gilbom_flyway
--

CREATE TABLE auth.user_permission_override (
    permission_override_id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    permission_id uuid NOT NULL,
    override_effect character varying(10) NOT NULL,
    reason character varying(1000) NOT NULL,
