    CONSTRAINT ck_user_permission_override_effect CHECK (((override_effect)::text = ANY ((ARRAY['ALLOW'::character varying, 'DENY'::character varying])::text[]))),
    CONSTRAINT ck_user_permission_override_expiry CHECK (((expires_at IS NULL) OR (expires_at > granted_at))),
    CONSTRAINT ck_user_permission_override_lifecycle CHECK ((((is_active = true) AND (revoked_by IS NULL) AND (revoked_at IS NULL) AND (revocation_reason IS NULL)) OR ((is_active = false) AND (revoked_by IS NOT NULL) AND (revoked_at IS NOT NULL) AND (revoked_at >= granted_at) AND (revocation_reason IS NOT NULL) AND ((revocation_reason)::text = btrim((revocation_reason)::text)) AND ((revocation_reason)::text <> ''::text) AND ((revocation_reason)::text !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT ck_user_permission_override_reason CHECK ((((reason)::text = btrim((reason)::text)) AND ((reason)::text <> ''::text) AND ((reason)::text !~ '[[:cntrl:]]'::text))),
    CONSTRAINT ck_user_permission_override_timestamps CHECK (((updated_at >= granted_at) AND ((revoked_at IS NULL) OR (updated_at >= revoked_at))))
);


