    assigned_by uuid NOT NULL,
    assigned_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    expires_at timestamp with time zone,
    ended_by uuid,
    ended_at timestamp with time zone,
    end_reason character varying(1000),
    updated_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    CONSTRAINT ck_user_robot_assignment_expiry CHECK (((expires_at IS NULL) OR (expires_at > assigned_at))),
    CONSTRAINT ck_user_robot_assignment_lifecycle CHECK ((((is_active = true) AND (ended_by IS NULL) AND (ended_at IS NULL) AND (end_reason IS NULL)) OR ((is_active = false) AND (ended_by IS NOT NULL) AND (ended_at IS NOT NULL) AND (ended_at >= assigned_at) AND (end_reason IS NOT NULL) AND ((end_reason)::text = btrim((end_reason)::text)) AND ((end_reason)::text <> ''::text) AND ((end_reason)::text !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT ck_user_robot_assignment_reason CHECK ((((reason)::text = btrim((reason)::text)) AND ((reason)::text <> ''::text) AND ((reason)::text !~ '[[:cntrl:]]'::text))),
    CONSTRAINT ck_user_robot_assignment_timestamps CHECK (((updated_at >= assigned_at) AND ((ended_at IS NULL) OR (updated_at >= ended_at)))),
    CONSTRAINT ck_user_robot_assignment_type CHECK (((assignment_type)::text = ANY ((ARRAY['VIEWER'::character varying, 'OPERATOR'::character varying, 'OWNER'::character varying])::text[])))
);


