--
-- Name: defect; Type: TABLE; Schema: defect; Owner: gilbom_flyway
--

CREATE TABLE defect.defect (
    defect_id uuid DEFAULT gen_random_uuid() NOT NULL,
    incident_code character varying(40) NOT NULL,
    asset_type character varying(30) DEFAULT 'BRAILLE_BLOCK'::character varying NOT NULL,
    block_type character varying(20) NOT NULL,
    defect_type character varying(40) NOT NULL,
    risk_level character varying(20) DEFAULT 'MEDIUM'::character varying NOT NULL,
    risk_score numeric(6,2),
    risk_rule_version character varying(30),
    risk_calculated_at timestamp with time zone,
    workflow_status character varying(30) DEFAULT 'NEW'::character varying NOT NULL,
    resolution character varying(40),
    resolution_note text,
    location public.geometry(Point,4326) NOT NULL,
    location_accuracy_m real,
    zone_id character varying(50) NOT NULL,
    patrol_area_id uuid,
    patrol_route_id uuid,
    location_label character varying(200),
    first_seen_at timestamp with time zone NOT NULL,
    last_seen_at timestamp with time zone NOT NULL,
    observation_count integer DEFAULT 1 NOT NULL,
    latest_confidence numeric(4,3),
    review_required boolean DEFAULT false NOT NULL,
    merged_into_defect_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_defect_asset_type CHECK (((asset_type)::text = 'BRAILLE_BLOCK'::text)),
    CONSTRAINT ck_defect_block_type CHECK (((block_type)::text = ANY ((ARRAY['LINEAR'::character varying, 'DOT'::character varying, 'UNKNOWN'::character varying])::text[]))),
    CONSTRAINT ck_defect_incident_code CHECK ((((incident_code)::text = btrim((incident_code)::text)) AND ((incident_code)::text <> ''::text))),
    CONSTRAINT ck_defect_latest_confidence CHECK (((latest_confidence IS NULL) OR ((latest_confidence >= (0)::numeric) AND (latest_confidence <= (1)::numeric)))),
    CONSTRAINT ck_defect_not_self_merged CHECK (((merged_into_defect_id IS NULL) OR (merged_into_defect_id <> defect_id))),
    CONSTRAINT ck_defect_observation_count CHECK ((observation_count >= 1)),
    CONSTRAINT ck_defect_observation_times CHECK ((last_seen_at >= first_seen_at)),
    CONSTRAINT ck_defect_resolution CHECK (((resolution IS NULL) OR ((resolution)::text = ANY ((ARRAY['REPAIRED'::character varying, 'CLEANED'::character varying, 'DUPLICATE'::character varying, 'REINSPECTION_REQUIRED'::character varying, 'NOT_APPLICABLE'::character varying])::text[])))),
    CONSTRAINT ck_defect_risk_level CHECK (((risk_level)::text = ANY ((ARRAY['LOW'::character varying, 'MEDIUM'::character varying, 'HIGH'::character varying, 'CRITICAL'::character varying])::text[]))),
    CONSTRAINT ck_defect_risk_score CHECK (((risk_score IS NULL) OR ((risk_score >= (0)::numeric) AND (risk_score <= (100)::numeric)))),
    CONSTRAINT ck_defect_route_requires_area CHECK (((patrol_route_id IS NULL) OR (patrol_area_id IS NOT NULL))),
    CONSTRAINT ck_defect_type CHECK (((defect_type)::text = ANY ((ARRAY['DAMAGED'::character varying, 'MISSING'::character varying, 'INSTALLATION_INVALID'::character varying, 'UNKNOWN_ANOMALY'::character varying])::text[]))),
    CONSTRAINT ck_defect_workflow_status CHECK (((workflow_status)::text = ANY ((ARRAY['NEW'::character varying, 'ACCEPTED'::character varying, 'IN_PROGRESS'::character varying, 'RESOLVED'::character varying, 'FALSE_POSITIVE'::character varying, 'REJECTED'::character varying])::text[])))
);


