    CONSTRAINT ck_defect_export_row_count CHECK (((row_count IS NULL) OR (row_count >= 0))),
    CONSTRAINT ck_defect_export_status CHECK (((job_status)::text = ANY ((ARRAY['QUEUED'::character varying, 'RUNNING'::character varying, 'COMPLETED'::character varying, 'FAILED'::character varying])::text[])))
);


