--
-- Name: anomaly_report; Type: TABLE; Schema: report; Owner: gilbom_flyway
--

CREATE TABLE report.anomaly_report (
    report_id uuid DEFAULT gen_random_uuid() NOT NULL,
    report_code character varying(30) NOT NULL,
    title character varying(200) NOT NULL,
    summary character varying(255),
    report_type character varying(20) NOT NULL,
    report_status character varying(20) DEFAULT 'DRAFT'::character varying NOT NULL,
    generation_method character varying(20) DEFAULT 'MANUAL'::character varying NOT NULL,
    creator_type character varying(20) DEFAULT 'USER'::character varying NOT NULL,
    period_from timestamp with time zone NOT NULL,
    period_to timestamp with time zone NOT NULL,
    filter_criteria jsonb,
    current_version_no integer DEFAULT 1 NOT NULL,
    approved_version_no integer,
    created_by uuid,
    approved_by uuid,
    approved_at timestamp with time zone,
    deleted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    approved_pdf_version_no integer,
    approved_pdf_storage_key character varying(500),
    approved_pdf_sha256 bytea,
    approved_pdf_created_at timestamp with time zone,
    CONSTRAINT ck_anomaly_report_approval CHECK (((((report_status)::text = 'APPROVED'::text) AND (approved_by IS NOT NULL) AND (approved_at IS NOT NULL) AND (approved_version_no IS NOT NULL)) OR (((report_status)::text <> 'APPROVED'::text) AND (approved_by IS NULL) AND (approved_at IS NULL) AND (approved_version_no IS NULL)))),
    CONSTRAINT ck_anomaly_report_approved_pdf_bundle CHECK ((((approved_pdf_version_no IS NULL) AND (approved_pdf_storage_key IS NULL) AND (approved_pdf_sha256 IS NULL) AND (approved_pdf_created_at IS NULL)) OR (((report_status)::text = 'APPROVED'::text) AND (approved_pdf_version_no = approved_version_no) AND ((approved_pdf_storage_key)::text = btrim((approved_pdf_storage_key)::text)) AND ((approved_pdf_storage_key)::text <> ''::text) AND (octet_length(approved_pdf_sha256) = 32) AND (approved_pdf_created_at IS NOT NULL) AND (approved_pdf_created_at >= approved_at)))),
    CONSTRAINT ck_anomaly_report_creator CHECK (((((creator_type)::text = 'USER'::text) AND (created_by IS NOT NULL)) OR (((creator_type)::text = 'SYSTEM'::text) AND (created_by IS NULL)))),
    CONSTRAINT ck_anomaly_report_creator_type CHECK (((creator_type)::text = ANY ((ARRAY['USER'::character varying, 'SYSTEM'::character varying])::text[]))),
    CONSTRAINT ck_anomaly_report_filter CHECK (((filter_criteria IS NULL) OR (jsonb_typeof(filter_criteria) = 'object'::text))),
    CONSTRAINT ck_anomaly_report_generation CHECK (((generation_method)::text = ANY ((ARRAY['MANUAL'::character varying, 'TEMPLATE'::character varying, 'LLM'::character varying, 'SYSTEM'::character varying])::text[]))),
    CONSTRAINT ck_anomaly_report_period CHECK ((period_to >= period_from)),
    CONSTRAINT ck_anomaly_report_soft_delete CHECK (((deleted_at IS NULL) OR ((report_status)::text = ANY ((ARRAY['DRAFT'::character varying, 'REJECTED'::character varying])::text[])))),
    CONSTRAINT ck_anomaly_report_status CHECK (((report_status)::text = ANY ((ARRAY['DRAFT'::character varying, 'IN_REVIEW'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying])::text[]))),
    CONSTRAINT ck_anomaly_report_timestamps CHECK ((updated_at >= created_at)),
    CONSTRAINT ck_anomaly_report_title CHECK ((((title)::text = btrim((title)::text)) AND ((title)::text <> ''::text))),
    CONSTRAINT ck_anomaly_report_type CHECK (((report_type)::text = ANY ((ARRAY['PERIODIC'::character varying, 'ISSUE'::character varying])::text[]))),
    CONSTRAINT ck_anomaly_report_version CHECK (((current_version_no >= 1) AND ((approved_version_no IS NULL) OR ((approved_version_no >= 1) AND (approved_version_no <= current_version_no)))))
);


ALTER TABLE report.anomaly_report OWNER TO gilbom_flyway;

