--
-- Name: report_version; Type: TABLE; Schema: report; Owner: gilbom_flyway
--

CREATE TABLE report.report_version (
    report_version_id uuid DEFAULT gen_random_uuid() NOT NULL,
    report_id uuid NOT NULL,
    version_no integer NOT NULL,
    title character varying(200) NOT NULL,
    summary character varying(255),
    period_from timestamp with time zone NOT NULL,
    period_to timestamp with time zone NOT NULL,
    content text NOT NULL,
    statistics jsonb DEFAULT '{}'::jsonb NOT NULL,
    llm_model character varying(100),
    prompt_version character varying(50),
    change_note character varying(500),
    creator_type character varying(20) DEFAULT 'USER'::character varying NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    generation_method character varying(20) NOT NULL,
    evidence_snapshot jsonb DEFAULT '{"defectIds": [], "missionIds": [], "patrolAreaIds": []}'::jsonb NOT NULL,
    generation_fallback_reason character varying(50),
    CONSTRAINT ck_report_version_creator CHECK (((((creator_type)::text = 'USER'::text) AND (created_by IS NOT NULL)) OR (((creator_type)::text = 'SYSTEM'::text) AND (created_by IS NULL)))),
    CONSTRAINT ck_report_version_creator_type CHECK (((creator_type)::text = ANY ((ARRAY['USER'::character varying, 'SYSTEM'::character varying])::text[]))),
    CONSTRAINT ck_report_version_evidence_snapshot CHECK (((jsonb_typeof(evidence_snapshot) = 'object'::text) AND (jsonb_typeof((evidence_snapshot -> 'defectIds'::text)) = 'array'::text) AND (jsonb_typeof((evidence_snapshot -> 'missionIds'::text)) = 'array'::text) AND (jsonb_typeof((evidence_snapshot -> 'patrolAreaIds'::text)) = 'array'::text))),
    CONSTRAINT ck_report_version_generation_fallback CHECK (((generation_fallback_reason IS NULL) OR (((generation_method)::text = 'TEMPLATE'::text) AND ((generation_fallback_reason)::text = ANY ((ARRAY['POLICY_DISABLED'::character varying, 'USER_DAILY_RATE_LIMIT'::character varying, 'DAILY_BUDGET_EXCEEDED'::character varying, 'CONCURRENCY_LIMIT'::character varying, 'IMAGE_EVIDENCE_INVALID'::character varying, 'LLM_UNAVAILABLE'::character varying, 'LLM_RESPONSE_INVALID'::character varying, 'QUOTA_GUARD_UNAVAILABLE'::character varying])::text[]))))),
    CONSTRAINT ck_report_version_generation_method CHECK (((generation_method)::text = ANY ((ARRAY['MANUAL'::character varying, 'TEMPLATE'::character varying, 'LLM'::character varying, 'SYSTEM'::character varying])::text[]))),
    CONSTRAINT ck_report_version_number CHECK ((version_no >= 1)),
    CONSTRAINT ck_report_version_period CHECK ((period_to >= period_from)),
    CONSTRAINT ck_report_version_statistics CHECK ((jsonb_typeof(statistics) = 'object'::text)),
    CONSTRAINT ck_report_version_title CHECK ((((title)::text = btrim((title)::text)) AND ((title)::text <> ''::text)))
);


ALTER TABLE report.report_version OWNER TO gilbom_flyway;

