--
-- Name: idempotency_request; Type: TABLE; Schema: request_control; Owner: gilbom_flyway
--

CREATE TABLE request_control.idempotency_request (
    idempotency_request_id uuid DEFAULT gen_random_uuid() NOT NULL,
    principal_type character varying(20) NOT NULL,
    principal_key_hash bytea NOT NULL,
    idempotency_key_hash bytea NOT NULL,
    request_fingerprint bytea NOT NULL,
    request_method character varying(10) NOT NULL,
    request_path character varying(500) NOT NULL,
    processing_status character varying(20) DEFAULT 'PROCESSING'::character varying NOT NULL,
    response_status smallint,
    response_headers jsonb,
    response_body jsonb,
    lease_expires_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    resource_type character varying(50),
    resource_id uuid,
    CONSTRAINT ck_idempotency_expiry CHECK (((lease_expires_at > created_at) AND (expires_at >= lease_expires_at))),
    CONSTRAINT ck_idempotency_hashes CHECK (((octet_length(principal_key_hash) = 32) AND (octet_length(idempotency_key_hash) = 32) AND (octet_length(request_fingerprint) = 32))),
    CONSTRAINT ck_idempotency_method CHECK (((request_method)::text = ANY ((ARRAY['POST'::character varying, 'PUT'::character varying, 'PATCH'::character varying, 'DELETE'::character varying])::text[]))),
    CONSTRAINT ck_idempotency_path CHECK ((((request_path)::text ~~ '/%'::text) AND ((request_path)::text = btrim((request_path)::text)))),
    CONSTRAINT ck_idempotency_principal_type CHECK (((principal_type)::text = ANY ((ARRAY['USER'::character varying, 'ROBOT'::character varying, 'SYSTEM'::character varying])::text[]))),
    CONSTRAINT ck_idempotency_resource CHECK ((((resource_type IS NULL) AND (resource_id IS NULL)) OR (((resource_type)::text ~ '^[A-Z][A-Z0-9_]{1,49}$'::text) AND (resource_id IS NOT NULL)))),
    CONSTRAINT ck_idempotency_response_headers CHECK (((response_headers IS NULL) OR (jsonb_typeof(response_headers) = 'object'::text))),
    CONSTRAINT ck_idempotency_status CHECK (((((processing_status)::text = 'PROCESSING'::text) AND (response_status IS NULL) AND (response_body IS NULL)) OR (((processing_status)::text = ANY ((ARRAY['SUCCEEDED'::character varying, 'FAILED'::character varying])::text[])) AND ((response_status >= 100) AND (response_status <= 599)) AND (response_body IS NOT NULL)))),
    CONSTRAINT ck_idempotency_timestamps CHECK ((updated_at >= created_at))
);


ALTER TABLE request_control.idempotency_request OWNER TO gilbom_flyway;

--
-- Name: TABLE idempotency_request; Type: COMMENT; Schema: request_control; Owner: gilbom_flyway
--

COMMENT ON TABLE request_control.idempotency_request IS '상태 변경 API의 동시 실행 방지와 완료 응답 replay 저장소';


--
-- Name: COLUMN idempotency_request.idempotency_key_hash; Type: COMMENT; Schema: request_control; Owner: gilbom_flyway
--

COMMENT ON COLUMN request_control.idempotency_request.idempotency_key_hash IS 'Idempotency-Key 원문 대신 저장하는 SHA-256';


--
-- Name: COLUMN idempotency_request.request_fingerprint; Type: COMMENT; Schema: request_control; Owner: gilbom_flyway
--

COMMENT ON COLUMN request_control.idempotency_request.request_fingerprint IS 'method, path, canonical body를 묶은 SHA-256';


--
-- Name: COLUMN idempotency_request.response_headers; Type: COMMENT; Schema: request_control; Owner: gilbom_flyway
--

COMMENT ON COLUMN request_control.idempotency_request.response_headers IS '재전송이 필요한 안전한 allowlist header만 저장하는 JSON object';


--
-- Name: COLUMN idempotency_request.response_body; Type: COMMENT; Schema: request_control; Owner: gilbom_flyway
--

COMMENT ON COLUMN request_control.idempotency_request.response_body IS '동일 요청 replay용 JSON 응답. Secret 응답에는 멱등 저장소를 사용하지 않는다.';


--
-- Name: COLUMN idempotency_request.lease_expires_at; Type: COMMENT; Schema: request_control; Owner: gilbom_flyway
--

COMMENT ON COLUMN request_control.idempotency_request.lease_expires_at IS 'PROCESSING 소유권 장애 복구를 위한 lease 만료 시각';


--
-- Name: COLUMN idempotency_request.resource_type; Type: COMMENT; Schema: request_control; Owner: gilbom_flyway
--

COMMENT ON COLUMN request_control.idempotency_request.resource_type IS '멱등 요청으로 생성된 리소스 종류. 보고서 생성은 REPORT를 저장한다.';


--
-- Name: COLUMN idempotency_request.resource_id; Type: COMMENT; Schema: request_control; Owner: gilbom_flyway
--

COMMENT ON COLUMN request_control.idempotency_request.resource_id IS '완료 응답 replay와 생성 결과 추적에 사용하는 리소스 UUID';


--
-- Name: llm_invocation_usage; Type: TABLE; Schema: request_control; Owner: gilbom_flyway
--

CREATE TABLE request_control.llm_invocation_usage (
    attempt_id uuid NOT NULL,
    usage_date date NOT NULL,
    actor_user_id uuid NOT NULL,
    provider character varying(20) NOT NULL,
    model_identifier character varying(100) NOT NULL,
    attempt_status character varying(20) NOT NULL,
    reserved_credits numeric(20,6) NOT NULL,
    accounted_credits numeric(20,6) NOT NULL,
    input_tokens integer,
    output_tokens integer,
    total_tokens integer,
    failure_code character varying(50),
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT ck_llm_invocation_completion CHECK (((((attempt_status)::text = 'STARTED'::text) AND (completed_at IS NULL) AND (failure_code IS NULL)) OR (((attempt_status)::text = 'SUCCEEDED'::text) AND (completed_at IS NOT NULL) AND (failure_code IS NULL)) OR (((attempt_status)::text = 'FAILED'::text) AND (completed_at IS NOT NULL) AND ((failure_code)::text = ANY ((ARRAY['RATE_LIMITED'::character varying, 'PROVIDER_5XX'::character varying, 'NETWORK_TIMEOUT'::character varying, 'PROVIDER_4XX'::character varying, 'CLIENT_FAILURE'::character varying, 'RESPONSE_INVALID'::character varying])::text[]))))),
    CONSTRAINT ck_llm_invocation_completion_time CHECK (((completed_at IS NULL) OR (completed_at >= started_at))),
    CONSTRAINT ck_llm_invocation_credits CHECK (((reserved_credits > (0)::numeric) AND (accounted_credits >= (0)::numeric))),
    CONSTRAINT ck_llm_invocation_model CHECK (((model_identifier)::text = ANY ((ARRAY['gpt-5.4-mini'::character varying, 'gpt-5.4'::character varying])::text[]))),
    CONSTRAINT ck_llm_invocation_provider CHECK (((provider)::text = 'GMS'::text)),
    CONSTRAINT ck_llm_invocation_status CHECK (((attempt_status)::text = ANY ((ARRAY['STARTED'::character varying, 'SUCCEEDED'::character varying, 'FAILED'::character varying])::text[]))),
    CONSTRAINT ck_llm_invocation_tokens CHECK ((((input_tokens IS NULL) OR (input_tokens >= 0)) AND ((output_tokens IS NULL) OR (output_tokens >= 0)) AND ((total_tokens IS NULL) OR (total_tokens >= 0))))
);


ALTER TABLE request_control.llm_invocation_usage OWNER TO gilbom_flyway;

--
-- Name: TABLE llm_invocation_usage; Type: COMMENT; Schema: request_control; Owner: gilbom_flyway
--

COMMENT ON TABLE request_control.llm_invocation_usage IS 'LLM 사용자별 일일 호출과 전체 일일 credit hard gate. Prompt·응답·이미지·credential 원문은 저장하지 않는다.';


--
-- Name: COLUMN llm_invocation_usage.accounted_credits; Type: COMMENT; Schema: request_control; Owner: gilbom_flyway
--

COMMENT ON COLUMN request_control.llm_invocation_usage.accounted_credits IS '호출 전에는 보수적 예약액, 성공 후 usage가 있으면 실제 계산액. 실패·unknown usage는 예약액을 유지한다.';


--
-- Name: COLUMN llm_invocation_usage.failure_code; Type: COMMENT; Schema: request_control; Owner: gilbom_flyway
--

COMMENT ON COLUMN request_control.llm_invocation_usage.failure_code IS 'Provider body나 예외 원문이 아닌 고정된 안전 실패 분류';


--
-- Name: mission; Type: TABLE; Schema: robot; Owner: gilbom_flyway
--

CREATE TABLE robot.mission (
    mission_id uuid DEFAULT gen_random_uuid() NOT NULL,
    mission_code character varying(100) NOT NULL,
    robot_id uuid NOT NULL,
    patrol_area_id uuid NOT NULL,
    patrol_route_id uuid NOT NULL,
    status character varying(20) DEFAULT 'CREATED'::character varying NOT NULL,
    scheduled_start_at timestamp with time zone,
    started_at timestamp with time zone,
    ended_at timestamp with time zone,
    progress_percent numeric(5,2) DEFAULT 0 NOT NULL,
    completion_reason character varying(100),
    result_duration_sec integer,
    result_incident_count integer,
    result_normal_detection_count integer,
    result_payload jsonb,
    created_by uuid NOT NULL,
    updated_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    planned_duration_sec integer DEFAULT 3600 NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    CONSTRAINT ck_mission_code CHECK ((((mission_code)::text = btrim((mission_code)::text)) AND ((mission_code)::text <> ''::text))),
    CONSTRAINT ck_mission_completion_result CHECK (((((status)::text = ANY ((ARRAY['COMPLETED'::character varying, 'CANCELLED'::character varying, 'FAILED'::character varying])::text[])) AND (completion_reason IS NOT NULL) AND (btrim((completion_reason)::text) <> ''::text)) OR (((status)::text <> ALL ((ARRAY['COMPLETED'::character varying, 'CANCELLED'::character varying, 'FAILED'::character varying])::text[])) AND (completion_reason IS NULL) AND (result_duration_sec IS NULL) AND (result_incident_count IS NULL) AND (result_normal_detection_count IS NULL) AND (result_payload IS NULL)))),
    CONSTRAINT ck_mission_lifecycle_times CHECK (((((status)::text = ANY ((ARRAY['CREATED'::character varying, 'READY'::character varying])::text[])) AND (started_at IS NULL) AND (ended_at IS NULL)) OR (((status)::text = ANY ((ARRAY['RUNNING'::character varying, 'PAUSED'::character varying])::text[])) AND (started_at IS NOT NULL) AND (ended_at IS NULL)) OR (((status)::text = 'COMPLETED'::text) AND (started_at IS NOT NULL) AND (ended_at IS NOT NULL) AND (ended_at >= started_at)) OR (((status)::text = ANY ((ARRAY['CANCELLED'::character varying, 'FAILED'::character varying])::text[])) AND (ended_at IS NOT NULL) AND ((started_at IS NULL) OR (ended_at >= started_at))))),
    CONSTRAINT ck_mission_planned_duration CHECK ((planned_duration_sec > 0)),
    CONSTRAINT ck_mission_progress CHECK ((((progress_percent >= (0)::numeric) AND (progress_percent <= (100)::numeric)) AND (((status)::text <> 'COMPLETED'::text) OR (progress_percent = (100)::numeric)))),
    CONSTRAINT ck_mission_result_counts CHECK ((((result_duration_sec IS NULL) OR (result_duration_sec >= 0)) AND ((result_incident_count IS NULL) OR (result_incident_count >= 0)) AND ((result_normal_detection_count IS NULL) OR (result_normal_detection_count >= 0)))),
    CONSTRAINT ck_mission_result_payload CHECK (((result_payload IS NULL) OR (jsonb_typeof(result_payload) = 'object'::text))),
    CONSTRAINT ck_mission_soft_delete CHECK ((((deleted_at IS NULL) AND (deleted_by IS NULL)) OR ((deleted_at IS NOT NULL) AND (deleted_by IS NOT NULL) AND (deleted_at >= created_at) AND ((status)::text = ANY ((ARRAY['COMPLETED'::character varying, 'CANCELLED'::character varying, 'FAILED'::character varying])::text[]))))),
    CONSTRAINT ck_mission_status CHECK (((status)::text = ANY ((ARRAY['CREATED'::character varying, 'READY'::character varying, 'RUNNING'::character varying, 'PAUSED'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'FAILED'::character varying])::text[]))),
    CONSTRAINT ck_mission_timestamps CHECK (((updated_at >= created_at) AND ((scheduled_start_at IS NULL) OR (scheduled_start_at >= created_at))))
);


ALTER TABLE robot.mission OWNER TO gilbom_flyway;

--
-- Name: TABLE mission; Type: COMMENT; Schema: robot; Owner: gilbom_flyway
--

COMMENT ON TABLE robot.mission IS 'Robot·Patrol Area·Patrol Route를 연결하는 순찰 Mission 정본';


--
-- Name: COLUMN mission.mission_id; Type: COMMENT; Schema: robot; Owner: gilbom_flyway
--

COMMENT ON COLUMN robot.mission.mission_id IS 'DB 내부 관계에 사용하는 Mission UUID PK';


--
-- Name: COLUMN mission.mission_code; Type: COMMENT; Schema: robot; Owner: gilbom_flyway
--

COMMENT ON COLUMN robot.mission.mission_code IS 'MQTT Payload의 문자열 mission_id. 예: MIS-20260726-001';


--
-- Name: COLUMN mission.planned_duration_sec; Type: COMMENT; Schema: robot; Owner: gilbom_flyway
--

COMMENT ON COLUMN robot.mission.planned_duration_sec IS '계획 수행시간(초). 진행률 분모이며 기존 Mission은 3600초로 Backfill';


--
-- Name: COLUMN mission.deleted_at; Type: COMMENT; Schema: robot; Owner: gilbom_flyway
--

COMMENT ON COLUMN robot.mission.deleted_at IS '종료 Mission을 목록에서 숨긴 관리자 논리 삭제 시각';


--
-- Name: COLUMN mission.deleted_by; Type: COMMENT; Schema: robot; Owner: gilbom_flyway
--

COMMENT ON COLUMN robot.mission.deleted_by IS '종료 Mission 논리 삭제를 실행한 관리자';


--
-- Name: CONSTRAINT ck_mission_lifecycle_times ON mission; Type: COMMENT; Schema: robot; Owner: gilbom_flyway
--

COMMENT ON CONSTRAINT ck_mission_lifecycle_times ON robot.mission IS '시작 전 CANCELLED/FAILED는 started_at NULL을 허용하고 종료 시각은 필수로 기록';


--
-- Name: mission_status_history; Type: TABLE; Schema: robot; Owner: gilbom_flyway
--

CREATE TABLE robot.mission_status_history (
    history_id uuid DEFAULT gen_random_uuid() NOT NULL,
    mission_id uuid NOT NULL,
    source_event_id uuid,
    transition_source character varying(10) NOT NULL,
    before_status character varying(20),
    after_status character varying(20) NOT NULL,
    transition_reason character varying(500),
    result_payload jsonb,
    changed_by uuid,
    occurred_at timestamp with time zone NOT NULL,
    received_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_mission_history_actor CHECK (((((transition_source)::text = 'MQTT'::text) AND (source_event_id IS NOT NULL) AND (changed_by IS NULL)) OR (((transition_source)::text = 'ADMIN'::text) AND (source_event_id IS NULL) AND (changed_by IS NOT NULL)) OR (((transition_source)::text = 'SYSTEM'::text) AND (source_event_id IS NULL) AND (changed_by IS NULL)))),
    CONSTRAINT ck_mission_history_after_status CHECK (((after_status)::text = ANY ((ARRAY['CREATED'::character varying, 'READY'::character varying, 'RUNNING'::character varying, 'PAUSED'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'FAILED'::character varying])::text[]))),
    CONSTRAINT ck_mission_history_before_status CHECK (((before_status IS NULL) OR ((before_status)::text = ANY ((ARRAY['CREATED'::character varying, 'READY'::character varying, 'RUNNING'::character varying, 'PAUSED'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'FAILED'::character varying])::text[])))),
    CONSTRAINT ck_mission_history_result CHECK (((result_payload IS NULL) OR (jsonb_typeof(result_payload) = 'object'::text))),
    CONSTRAINT ck_mission_history_source CHECK (((transition_source)::text = ANY ((ARRAY['MQTT'::character varying, 'ADMIN'::character varying, 'SYSTEM'::character varying])::text[])))
);


ALTER TABLE robot.mission_status_history OWNER TO gilbom_flyway;

--
-- Name: TABLE mission_status_history; Type: COMMENT; Schema: robot; Owner: gilbom_flyway
--

COMMENT ON TABLE robot.mission_status_history IS 'REST·MQTT·SYSTEM Mission 상태 전이의 append-only 이력';


