CREATE TABLE robot.patrol_area (
    patrol_area_id uuid DEFAULT gen_random_uuid() NOT NULL,
    area_code character varying(50) NOT NULL,
    area_name character varying(100) NOT NULL,
    boundary public.geometry(Geometry,4326) NOT NULL,
    lifecycle_status character varying(20) DEFAULT 'ACTIVE'::character varying NOT NULL,
    created_by uuid NOT NULL,
    updated_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_patrol_area_code CHECK ((((area_code)::text = btrim((area_code)::text)) AND ((area_code)::text <> ''::text))),
    CONSTRAINT ck_patrol_area_geometry_type CHECK ((public.geometrytype(boundary) = ANY (ARRAY['POLYGON'::text, 'MULTIPOLYGON'::text]))),
    CONSTRAINT ck_patrol_area_geometry_valid CHECK (((public.st_srid(boundary) = 4326) AND (NOT public.st_isempty(boundary)) AND public.st_isvalid(boundary))),
    CONSTRAINT ck_patrol_area_lifecycle CHECK (((lifecycle_status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'INACTIVE'::character varying, 'ARCHIVED'::character varying])::text[]))),
    CONSTRAINT ck_patrol_area_name CHECK ((((area_name)::text = btrim((area_name)::text)) AND ((area_name)::text <> ''::text))),
    CONSTRAINT ck_patrol_area_timestamps CHECK ((updated_at >= created_at))
);


ALTER TABLE robot.patrol_area OWNER TO gilbom_flyway;

--
-- Name: TABLE patrol_area; Type: COMMENT; Schema: robot; Owner: gilbom_flyway
