    lifecycle_status character varying(20) DEFAULT 'DRAFT'::character varying NOT NULL,
    created_by uuid NOT NULL,
    updated_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_patrol_route_code CHECK ((((route_code)::text = btrim((route_code)::text)) AND ((route_code)::text <> ''::text))),
    CONSTRAINT ck_patrol_route_geometry_type CHECK ((public.geometrytype(route_geometry) = ANY (ARRAY['LINESTRING'::text, 'MULTILINESTRING'::text]))),
    CONSTRAINT ck_patrol_route_geometry_valid CHECK (((public.st_srid(route_geometry) = 4326) AND (NOT public.st_isempty(route_geometry)) AND public.st_isvalid(route_geometry))),
    CONSTRAINT ck_patrol_route_lifecycle CHECK (((lifecycle_status)::text = ANY ((ARRAY['DRAFT'::character varying, 'ACTIVE'::character varying, 'INACTIVE'::character varying, 'ARCHIVED'::character varying])::text[]))),
    CONSTRAINT ck_patrol_route_name CHECK ((((route_name)::text = btrim((route_name)::text)) AND ((route_name)::text <> ''::text))),
    CONSTRAINT ck_patrol_route_timestamps CHECK ((updated_at >= created_at)),
    CONSTRAINT ck_patrol_route_version CHECK ((route_version >= 1))
);


