    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_robot_mqtt_id_not_blank CHECK ((((mqtt_id)::text = btrim((mqtt_id)::text)) AND ((mqtt_id)::text <> ''::text))),
    CONSTRAINT ck_robot_name_not_blank CHECK ((((robot_name)::text = btrim((robot_name)::text)) AND ((robot_name)::text <> ''::text))),
    CONSTRAINT ck_robot_operational_status CHECK (((operational_status)::text = ANY ((ARRAY['PROVISIONING'::character varying, 'ACTIVE'::character varying, 'INACTIVE'::character varying, 'MAINTENANCE'::character varying, 'DISABLED'::character varying])::text[]))),
    CONSTRAINT ck_robot_serial_number_not_blank CHECK ((((serial_number)::text = btrim((serial_number)::text)) AND ((serial_number)::text <> ''::text))),
    CONSTRAINT ck_robot_timestamps CHECK ((updated_at >= registered_at))
);


