--
-- Name: robot_command; Type: TABLE; Schema: robot; Owner: gilbom_flyway
--

CREATE TABLE robot.robot_command (
    command_id uuid NOT NULL,
    schema_version character varying(10) NOT NULL,
    robot_id uuid NOT NULL,
    mission_id uuid,
    patrol_area_id uuid,
    command_type character varying(40) NOT NULL,
    command_status character varying(20) NOT NULL,
    parameters jsonb NOT NULL,
    requested_by_type character varying(10) NOT NULL,
    requested_by_user_id uuid,
    issued_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    sent_at timestamp with time zone,
    accepted_at timestamp with time zone,
    completed_at timestamp with time zone,
    publish_attempt_count integer DEFAULT 0 NOT NULL,
    last_error_code character varying(100),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_robot_command_expiry CHECK ((expires_at > issued_at)),
    CONSTRAINT ck_robot_command_failure CHECK (((((command_status)::text = 'PUBLISH_FAILED'::text) AND (last_error_code IS NOT NULL) AND (btrim((last_error_code)::text) <> ''::text)) OR ((command_status)::text <> 'PUBLISH_FAILED'::text))),
    CONSTRAINT ck_robot_command_lifecycle CHECK (((((command_status)::text = 'CREATED'::text) AND (sent_at IS NULL)) OR ((command_status)::text <> 'CREATED'::text))),
    CONSTRAINT ck_robot_command_parameters CHECK ((jsonb_typeof(parameters) = 'object'::text)),
    CONSTRAINT ck_robot_command_publish_attempts CHECK ((publish_attempt_count >= 0)),
    CONSTRAINT ck_robot_command_requester CHECK (((((requested_by_type)::text = 'ADMIN'::text) AND (requested_by_user_id IS NOT NULL)) OR (((requested_by_type)::text = 'SYSTEM'::text) AND (requested_by_user_id IS NULL)))),
    CONSTRAINT ck_robot_command_schema CHECK (((schema_version)::text = '2.0'::text)),
    CONSTRAINT ck_robot_command_status CHECK (((command_status)::text = ANY ((ARRAY['CREATED'::character varying, 'SENT'::character varying, 'ACCEPTED'::character varying, 'COMPLETED'::character varying, 'FAILED'::character varying, 'REJECTED'::character varying, 'EXPIRED'::character varying, 'PUBLISH_FAILED'::character varying])::text[]))),
    CONSTRAINT ck_robot_command_timestamps CHECK (((updated_at >= created_at) AND (expires_at > issued_at) AND ((sent_at IS NULL) OR (sent_at >= issued_at)) AND ((accepted_at IS NULL) OR (accepted_at >= issued_at)) AND ((completed_at IS NULL) OR (completed_at >= issued_at)))),
    CONSTRAINT ck_robot_command_type CHECK (((command_type)::text = ANY ((ARRAY['START_MISSION'::character varying, 'PAUSE_MISSION'::character varying, 'RESUME_MISSION'::character varying, 'COMPLETE_MISSION'::character varying, 'CANCEL_MISSION'::character varying, 'EMERGENCY_STOP'::character varying, 'CLEAR_EMERGENCY_STOP'::character varying])::text[])))
);


ALTER TABLE robot.robot_command OWNER TO gilbom_flyway;

--
-- Name: TABLE robot_command; Type: COMMENT; Schema: robot; Owner: gilbom_flyway
--

COMMENT ON TABLE robot.robot_command IS 'REST 접수부터 MQTT 발행, ACK, 완료, 만료까지 관리하는 로봇 명령';


--
-- Name: COLUMN robot_command.mission_id; Type: COMMENT; Schema: robot; Owner: gilbom_flyway
