--
-- Name: COLUMN robot_command.patrol_area_id; Type: COMMENT; Schema: robot; Owner: gilbom_flyway
--

COMMENT ON COLUMN robot.robot_command.patrol_area_id IS 'START_MISSION의 zone_id와 일치함을 검증한 Patrol Area UUID';


--
-- Name: robot_command_result; Type: TABLE; Schema: robot; Owner: gilbom_flyway
--

CREATE TABLE robot.robot_command_result (
    result_id uuid NOT NULL,
    command_id uuid NOT NULL,
    robot_id uuid NOT NULL,
    schema_version character varying(10) NOT NULL,
    result_status character varying(20) NOT NULL,
    robot_received_at timestamp with time zone NOT NULL,
    robot_completed_at timestamp with time zone,
    reason_code character varying(100) NOT NULL,
    resulting_mode character varying(20) NOT NULL,
    resulting_reason_code character varying(50) NOT NULL,
    server_received_at timestamp with time zone NOT NULL,
    raw_payload jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_robot_command_result_completion CHECK (((((result_status)::text = 'ACCEPTED'::text) AND (robot_completed_at IS NULL)) OR (((result_status)::text <> 'ACCEPTED'::text) AND (robot_completed_at IS NOT NULL)))),
    CONSTRAINT ck_robot_command_result_mode CHECK (((resulting_mode)::text = ANY ((ARRAY['BOOTING'::character varying, 'READY'::character varying, 'PATROLLING'::character varying, 'PAUSED'::character varying, 'SAFE_STOP'::character varying, 'ERROR'::character varying, 'SHUTTING_DOWN'::character varying])::text[]))),
    CONSTRAINT ck_robot_command_result_payload CHECK ((jsonb_typeof(raw_payload) = 'object'::text)),
    CONSTRAINT ck_robot_command_result_reason CHECK ((btrim((reason_code)::text) <> ''::text)),
    CONSTRAINT ck_robot_command_result_schema CHECK (((schema_version)::text = '2.0'::text)),
    CONSTRAINT ck_robot_command_result_state_reason CHECK (((resulting_reason_code)::text = ANY ((ARRAY['NONE'::character varying, 'REMOTE_PAUSE'::character varying, 'REMOTE_ESTOP'::character varying, 'OBSTACLE'::character varying, 'BOUNDARY_LOST'::character varying, 'LOW_BATTERY'::character varying, 'CRITICAL_BATTERY'::character varying, 'LIDAR_FAULT'::character varying, 'MOTOR_FAULT'::character varying, 'INTERNAL_ERROR'::character varying])::text[]))),
    CONSTRAINT ck_robot_command_result_status CHECK (((result_status)::text = ANY ((ARRAY['ACCEPTED'::character varying, 'COMPLETED'::character varying, 'FAILED'::character varying, 'REJECTED'::character varying, 'EXPIRED'::character varying])::text[]))),
    CONSTRAINT ck_robot_command_result_times CHECK (((robot_completed_at IS NULL) OR (robot_completed_at >= robot_received_at)))
);


ALTER TABLE robot.robot_command_result OWNER TO gilbom_flyway;

--
-- Name: TABLE robot_command_result; Type: COMMENT; Schema: robot; Owner: gilbom_flyway
--

COMMENT ON TABLE robot.robot_command_result IS 'MQTT commands/result로 수신한 append-only 명령 처리 결과';


--
-- Name: robot_credential; Type: TABLE; Schema: robot; Owner: gilbom_flyway
--

CREATE TABLE robot.robot_credential (
    credential_id uuid DEFAULT gen_random_uuid() NOT NULL,
    robot_id uuid NOT NULL,
    credential_type character varying(30) DEFAULT 'MQTT_PASSWORD'::character varying NOT NULL,
    credential_version integer NOT NULL,
    secret_hash text NOT NULL,
    secret_fingerprint character(64) NOT NULL,
    credential_status character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    issued_by uuid NOT NULL,
    issued_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    activated_at timestamp with time zone,
    revoked_by uuid,
    revoked_at timestamp with time zone,
    revocation_reason character varying(100),
    last_provision_error_code character varying(100),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_robot_credential_activation CHECK ((((credential_status)::text <> 'ACTIVE'::text) OR (activated_at IS NOT NULL))),
    CONSTRAINT ck_robot_credential_expiry CHECK (((expires_at > issued_at) AND (expires_at <= (issued_at + '180 days'::interval)))),
    CONSTRAINT ck_robot_credential_failure CHECK (((((credential_status)::text = 'FAILED'::text) AND (last_provision_error_code IS NOT NULL) AND (btrim((last_provision_error_code)::text) <> ''::text)) OR (((credential_status)::text <> 'FAILED'::text) AND (last_provision_error_code IS NULL)))),
    CONSTRAINT ck_robot_credential_fingerprint CHECK ((secret_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ck_robot_credential_hash_not_blank CHECK ((btrim(secret_hash) <> ''::text)),
    CONSTRAINT ck_robot_credential_revocation CHECK (((((credential_status)::text = 'REVOKED'::text) AND (revoked_at IS NOT NULL) AND (revoked_by IS NOT NULL) AND (revocation_reason IS NOT NULL) AND (btrim((revocation_reason)::text) <> ''::text)) OR (((credential_status)::text <> 'REVOKED'::text) AND (revoked_at IS NULL) AND (revoked_by IS NULL) AND (revocation_reason IS NULL)))),
    CONSTRAINT ck_robot_credential_status CHECK (((credential_status)::text = ANY ((ARRAY['PENDING'::character varying, 'ACTIVE'::character varying, 'REVOKED'::character varying, 'EXPIRED'::character varying, 'FAILED'::character varying])::text[]))),
    CONSTRAINT ck_robot_credential_timestamps CHECK (((created_at >= issued_at) AND (updated_at >= created_at) AND ((activated_at IS NULL) OR (activated_at >= issued_at)) AND ((revoked_at IS NULL) OR (revoked_at >= issued_at)))),
    CONSTRAINT ck_robot_credential_type CHECK (((credential_type)::text = 'MQTT_PASSWORD'::text)),
    CONSTRAINT ck_robot_credential_version CHECK ((credential_version > 0))
);


