--
-- Name: session_security_state; Type: TABLE; Schema: session_store; Owner: gilbom_flyway
--

CREATE TABLE session_store.session_security_state (
    session_primary_id character(36) NOT NULL,
    user_id uuid,
    authentication_state character varying(40) DEFAULT 'ANONYMOUS'::character varying NOT NULL,
    absolute_expiry_time bigint,
    authentication_challenge_expires_at bigint,
    authentication_challenge_failure_count smallint DEFAULT 0 NOT NULL,
    created_time bigint NOT NULL,
    updated_time bigint NOT NULL,
    authentication_challenge_started_time bigint,
    CONSTRAINT ck_session_authentication_state CHECK (((authentication_state)::text = ANY ((ARRAY['ANONYMOUS'::character varying, 'PASSWORD_CHANGE_REQUIRED'::character varying, 'MFA_ENROLLMENT_REQUIRED'::character varying, 'MFA_REQUIRED'::character varying, 'AUTHENTICATED'::character varying])::text[]))),
    CONSTRAINT ck_session_challenge_failure_count CHECK (((authentication_challenge_failure_count >= 0) AND (authentication_challenge_failure_count <= 5))),
    CONSTRAINT ck_session_security_context CHECK (((((authentication_state)::text = 'ANONYMOUS'::text) AND (user_id IS NULL) AND (absolute_expiry_time IS NULL) AND (authentication_challenge_started_time IS NULL) AND (authentication_challenge_expires_at IS NULL) AND (authentication_challenge_failure_count = 0)) OR (((authentication_state)::text = ANY ((ARRAY['PASSWORD_CHANGE_REQUIRED'::character varying, 'MFA_ENROLLMENT_REQUIRED'::character varying, 'MFA_REQUIRED'::character varying])::text[])) AND (user_id IS NOT NULL) AND (absolute_expiry_time IS NOT NULL) AND (authentication_challenge_started_time IS NOT NULL) AND (authentication_challenge_expires_at IS NOT NULL)) OR (((authentication_state)::text = 'AUTHENTICATED'::text) AND (user_id IS NOT NULL) AND (absolute_expiry_time IS NOT NULL) AND (authentication_challenge_started_time IS NULL) AND (authentication_challenge_expires_at IS NULL) AND (authentication_challenge_failure_count = 0)))),
    CONSTRAINT ck_session_security_lifetime_limits CHECK (((((authentication_state)::text = 'ANONYMOUS'::text) AND (absolute_expiry_time IS NULL)) OR (((authentication_state)::text = ANY ((ARRAY['PASSWORD_CHANGE_REQUIRED'::character varying, 'MFA_ENROLLMENT_REQUIRED'::character varying, 'MFA_REQUIRED'::character varying])::text[])) AND (authentication_challenge_expires_at <= (authentication_challenge_started_time + 300000)) AND (absolute_expiry_time = authentication_challenge_expires_at)) OR (((authentication_state)::text = 'AUTHENTICATED'::text) AND (absolute_expiry_time <= (updated_time + 28800000))))),
    CONSTRAINT ck_session_security_timestamps CHECK (((created_time >= 0) AND (updated_time >= created_time) AND ((absolute_expiry_time IS NULL) OR (absolute_expiry_time > created_time)) AND ((authentication_challenge_started_time IS NULL) OR (authentication_challenge_started_time >= created_time)) AND ((authentication_challenge_expires_at IS NULL) OR ((authentication_challenge_started_time IS NOT NULL) AND (authentication_challenge_expires_at > authentication_challenge_started_time)))))
);


