    CONSTRAINT ck_robot_image_bucket CHECK ((((bucket_name)::text = btrim((bucket_name)::text)) AND ((bucket_name)::text <> ''::text))),
    CONSTRAINT ck_robot_image_content_type CHECK (((content_type)::text = 'image/jpeg'::text)),
    CONSTRAINT ck_robot_image_dimensions CHECK (((image_width > 0) AND (image_height > 0))),
    CONSTRAINT ck_robot_image_lifecycle CHECK (((((image_status)::text = 'DELETED'::text) AND (deleted_at IS NOT NULL)) OR (((image_status)::text <> 'DELETED'::text) AND (deleted_at IS NULL)))),
    CONSTRAINT ck_robot_image_metadata CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT ck_robot_image_object_key CHECK ((((object_key)::text = btrim((object_key)::text)) AND ((object_key)::text <> ''::text))),
