    CONSTRAINT ck_robot_image_api_key_prefix CHECK ((((key_prefix)::text = btrim((key_prefix)::text)) AND ((key_prefix)::text <> ''::text))),
    CONSTRAINT ck_robot_image_api_key_status CHECK (((key_status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'REVOKED'::character varying])::text[]))),
