    CONSTRAINT ck_robot_boot_session_reason CHECK (((offline_reason IS NULL) OR ((offline_reason)::text = ANY ((ARRAY['GRACEFUL_SHUTDOWN'::character varying, 'CRITICAL_BATTERY_SHUTDOWN'::character varying, 'SYSTEM_FAULT_SHUTDOWN'::character varying, 'UNGRACEFUL_DISCONNECT'::character varying, 'HEARTBEAT_TIMEOUT'::character varying, 'REPLACED_BY_NEW_BOOT'::character varying, 'MIGRATED_HISTORY'::character varying])::text[])))),
