    storage_health character varying(20),
    telemetry_seq bigint,
    telemetry_sampled_at timestamp with time zone,
    telemetry_received_at timestamp with time zone,
    position_valid boolean,
    "position" public.geometry(Point,4326),
    heading_deg double precision,
    moving boolean,
    speed_mps double precision,
    jetson_temp_c double precision,
    overall_health_status character varying(20) DEFAULT 'UNKNOWN'::character varying NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_robot_current_battery CHECK (((battery_valid IS NULL) OR ((battery_valid = true) AND (battery_percent IS NOT NULL) AND ((battery_percent >= 0.0) AND (battery_percent <= 100.0)) AND ((battery_state)::text = ANY ((ARRAY['NORMAL'::character varying, 'LOW'::character varying, 'CRITICAL'::character varying])::text[]))) OR ((battery_valid = false) AND (battery_percent IS NULL) AND ((battery_state)::text = 'UNKNOWN'::text) AND (battery_source IS NULL)))),
    CONSTRAINT ck_robot_current_battery_source CHECK (((battery_source IS NULL) OR ((battery_source)::text = ANY ((ARRAY['MEASURED'::character varying, 'ESTIMATED'::character varying])::text[])))),
    CONSTRAINT ck_robot_current_connectivity CHECK (((connectivity_status)::text = ANY ((ARRAY['ONLINE'::character varying, 'OFFLINE'::character varying])::text[]))),
    CONSTRAINT ck_robot_current_estimated_runtime CHECK (((estimated_runtime_sec IS NULL) OR (estimated_runtime_sec >= 0))),
    CONSTRAINT ck_robot_current_heading CHECK (((heading_deg IS NULL) OR ((heading_deg >= (0.0)::double precision) AND (heading_deg < (360.0)::double precision)))),
    CONSTRAINT ck_robot_current_health CHECK ((((camera_health IS NULL) OR ((camera_health)::text = ANY ((ARRAY['OK'::character varying, 'DEGRADED'::character varying, 'FAULT'::character varying, 'UNKNOWN'::character varying])::text[]))) AND ((lidar_health IS NULL) OR ((lidar_health)::text = ANY ((ARRAY['OK'::character varying, 'DEGRADED'::character varying, 'FAULT'::character varying, 'UNKNOWN'::character varying])::text[]))) AND ((gps_health IS NULL) OR ((gps_health)::text = ANY ((ARRAY['OK'::character varying, 'DEGRADED'::character varying, 'FAULT'::character varying, 'UNKNOWN'::character varying])::text[]))) AND ((battery_health IS NULL) OR ((battery_health)::text = ANY ((ARRAY['OK'::character varying, 'DEGRADED'::character varying, 'FAULT'::character varying, 'UNKNOWN'::character varying])::text[]))) AND ((motor_health IS NULL) OR ((motor_health)::text = ANY ((ARRAY['OK'::character varying, 'DEGRADED'::character varying, 'FAULT'::character varying, 'UNKNOWN'::character varying])::text[]))) AND ((storage_health IS NULL) OR ((storage_health)::text = ANY ((ARRAY['OK'::character varying, 'DEGRADED'::character varying, 'FAULT'::character varying, 'UNKNOWN'::character varying])::text[]))))),
    CONSTRAINT ck_robot_current_last_seen_seq CHECK (((last_seen_seq IS NULL) OR (last_seen_seq >= 1))),
    CONSTRAINT ck_robot_current_mission_status CHECK (((mission_status IS NULL) OR ((mission_status)::text = ANY ((ARRAY['READY'::character varying, 'RUNNING'::character varying, 'PAUSED'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'FAILED'::character varying])::text[])))),
    CONSTRAINT ck_robot_current_mode CHECK (((robot_mode IS NULL) OR ((robot_mode)::text = ANY ((ARRAY['BOOTING'::character varying, 'READY'::character varying, 'PATROLLING'::character varying, 'PAUSED'::character varying, 'SAFE_STOP'::character varying, 'ERROR'::character varying, 'SHUTTING_DOWN'::character varying])::text[])))),
    CONSTRAINT ck_robot_current_overall_health CHECK (((overall_health_status)::text = ANY ((ARRAY['OK'::character varying, 'WARNING'::character varying, 'CRITICAL'::character varying, 'UNKNOWN'::character varying])::text[]))),
    CONSTRAINT ck_robot_current_position CHECK (((position_valid IS NULL) OR (position_valid = false) OR ("position" IS NOT NULL))),
    CONSTRAINT ck_robot_current_reason CHECK (((state_reason_code IS NULL) OR ((state_reason_code)::text = ANY ((ARRAY['NONE'::character varying, 'REMOTE_PAUSE'::character varying, 'REMOTE_ESTOP'::character varying, 'OBSTACLE'::character varying, 'BOUNDARY_LOST'::character varying, 'LOW_BATTERY'::character varying, 'CRITICAL_BATTERY'::character varying, 'LIDAR_FAULT'::character varying, 'MOTOR_FAULT'::character varying, 'INTERNAL_ERROR'::character varying])::text[])))),
    CONSTRAINT ck_robot_current_speed CHECK (((speed_mps IS NULL) OR (speed_mps >= (0.0)::double precision))),
    CONSTRAINT ck_robot_current_state_seq CHECK (((state_seq IS NULL) OR (state_seq >= 1))),
    CONSTRAINT ck_robot_current_state_version CHECK (((state_schema_version IS NULL) OR ((state_schema_version)::text = '2.0'::text))),
    CONSTRAINT ck_robot_current_telemetry_seq CHECK (((telemetry_seq IS NULL) OR (telemetry_seq >= 1)))
);


