--
-- Name: robot_event; Type: TABLE; Schema: telemetry; Owner: gilbom_flyway
--

CREATE TABLE telemetry.robot_event (
    event_id uuid NOT NULL,
    schema_version character varying(10) NOT NULL,
    robot_id uuid NOT NULL,
    boot_id uuid NOT NULL,
    seq bigint NOT NULL,
    mission_id uuid,
    event_type character varying(50) NOT NULL,
    source_component character varying(20) NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    sent_at timestamp with time zone NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    raw_payload jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_robot_event_mission CHECK ((((event_type)::text <> ALL ((ARRAY['MISSION_STARTED'::character varying, 'MISSION_PAUSED'::character varying, 'MISSION_RESUMED'::character varying, 'MISSION_COMPLETED'::character varying, 'MISSION_CANCELLED'::character varying, 'MISSION_FAILED'::character varying])::text[])) OR (mission_id IS NOT NULL))),
    CONSTRAINT ck_robot_event_payload CHECK ((jsonb_typeof(raw_payload) = 'object'::text)),
    CONSTRAINT ck_robot_event_schema CHECK (((schema_version)::text = '2.0'::text)),
    CONSTRAINT ck_robot_event_sequence CHECK ((seq >= 1)),
    CONSTRAINT ck_robot_event_source CHECK (((((event_type)::text = 'BRAILLE_BLOCK_INCIDENT_DETECTED'::text) AND ((source_component)::text = 'ai'::text)) OR (((event_type)::text = ANY ((ARRAY['BATTERY_LOW'::character varying, 'BATTERY_CRITICAL'::character varying, 'BATTERY_RECOVERED'::character varying, 'BATTERY_SENSOR_FAULT'::character varying, 'BATTERY_SENSOR_RECOVERED'::character varying])::text[])) AND ((source_component)::text = 'power'::text)) OR (((event_type)::text = ANY ((ARRAY['SAFETY_STOPPED'::character varying, 'SAFETY_CLEARED'::character varying, 'SENSOR_FAULT'::character varying, 'SENSOR_RECOVERED'::character varying])::text[])) AND ((source_component)::text = 'safety'::text)) OR (((event_type)::text = ANY ((ARRAY['MISSION_STARTED'::character varying, 'MISSION_PAUSED'::character varying, 'MISSION_RESUMED'::character varying, 'MISSION_COMPLETED'::character varying, 'MISSION_CANCELLED'::character varying, 'MISSION_FAILED'::character varying])::text[])) AND ((source_component)::text = 'mission'::text)))),
    CONSTRAINT ck_robot_event_times CHECK ((sent_at >= occurred_at)),
    CONSTRAINT ck_robot_event_type CHECK (((event_type)::text = ANY ((ARRAY['BRAILLE_BLOCK_INCIDENT_DETECTED'::character varying, 'BATTERY_LOW'::character varying, 'BATTERY_CRITICAL'::character varying, 'BATTERY_RECOVERED'::character varying, 'BATTERY_SENSOR_FAULT'::character varying, 'BATTERY_SENSOR_RECOVERED'::character varying, 'SAFETY_STOPPED'::character varying, 'SAFETY_CLEARED'::character varying, 'SENSOR_FAULT'::character varying, 'SENSOR_RECOVERED'::character varying, 'MISSION_STARTED'::character varying, 'MISSION_PAUSED'::character varying, 'MISSION_RESUMED'::character varying, 'MISSION_COMPLETED'::character varying, 'MISSION_CANCELLED'::character varying, 'MISSION_FAILED'::character varying])::text[])))
);


