--
-- Name: robot_status_history; Type: TABLE; Schema: telemetry; Owner: gilbom_flyway
--

CREATE TABLE telemetry.robot_status_history (
    status_history_id uuid DEFAULT gen_random_uuid() NOT NULL,
    robot_id uuid NOT NULL,
    boot_id uuid NOT NULL,
    event_kind character varying(20) NOT NULL,
    seq bigint,
    connectivity_status character varying(10),
    robot_mode character varying(20),
    reason_code character varying(50),
    mission_status character varying(20),
    battery_valid boolean,
    battery_percent numeric(5,2),
    battery_state character varying(20),
    camera_health character varying(20),
    lidar_health character varying(20),
    gps_health character varying(20),
    battery_health character varying(20),
    motor_health character varying(20),
    storage_health character varying(20),
    observed_at timestamp with time zone NOT NULL,
    received_at timestamp with time zone NOT NULL,
    raw_payload jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_robot_status_history_battery CHECK (((battery_valid IS NULL) OR ((battery_valid = true) AND (battery_percent IS NOT NULL) AND ((battery_percent >= 0.0) AND (battery_percent <= 100.0)) AND ((battery_state)::text = ANY ((ARRAY['NORMAL'::character varying, 'LOW'::character varying, 'CRITICAL'::character varying])::text[]))) OR ((battery_valid = false) AND (battery_percent IS NULL) AND ((battery_state)::text = 'UNKNOWN'::text)))),
    CONSTRAINT ck_robot_status_history_connectivity CHECK (((connectivity_status IS NULL) OR ((connectivity_status)::text = ANY ((ARRAY['ONLINE'::character varying, 'OFFLINE'::character varying])::text[])))),
    CONSTRAINT ck_robot_status_history_health CHECK ((((camera_health IS NULL) OR ((camera_health)::text = ANY ((ARRAY['OK'::character varying, 'DEGRADED'::character varying, 'FAULT'::character varying, 'UNKNOWN'::character varying])::text[]))) AND ((lidar_health IS NULL) OR ((lidar_health)::text = ANY ((ARRAY['OK'::character varying, 'DEGRADED'::character varying, 'FAULT'::character varying, 'UNKNOWN'::character varying])::text[]))) AND ((gps_health IS NULL) OR ((gps_health)::text = ANY ((ARRAY['OK'::character varying, 'DEGRADED'::character varying, 'FAULT'::character varying, 'UNKNOWN'::character varying])::text[]))) AND ((battery_health IS NULL) OR ((battery_health)::text = ANY ((ARRAY['OK'::character varying, 'DEGRADED'::character varying, 'FAULT'::character varying, 'UNKNOWN'::character varying])::text[]))) AND ((motor_health IS NULL) OR ((motor_health)::text = ANY ((ARRAY['OK'::character varying, 'DEGRADED'::character varying, 'FAULT'::character varying, 'UNKNOWN'::character varying])::text[]))) AND ((storage_health IS NULL) OR ((storage_health)::text = ANY ((ARRAY['OK'::character varying, 'DEGRADED'::character varying, 'FAULT'::character varying, 'UNKNOWN'::character varying])::text[]))))),
    CONSTRAINT ck_robot_status_history_kind CHECK (((event_kind)::text = ANY ((ARRAY['PRESENCE'::character varying, 'STATE'::character varying, 'TIMEOUT'::character varying])::text[]))),
    CONSTRAINT ck_robot_status_history_mission CHECK (((mission_status IS NULL) OR ((mission_status)::text = ANY ((ARRAY['READY'::character varying, 'RUNNING'::character varying, 'PAUSED'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'FAILED'::character varying])::text[])))),
    CONSTRAINT ck_robot_status_history_mode CHECK (((robot_mode IS NULL) OR ((robot_mode)::text = ANY ((ARRAY['BOOTING'::character varying, 'READY'::character varying, 'PATROLLING'::character varying, 'PAUSED'::character varying, 'SAFE_STOP'::character varying, 'ERROR'::character varying, 'SHUTTING_DOWN'::character varying])::text[])))),
    CONSTRAINT ck_robot_status_history_raw_payload CHECK ((jsonb_typeof(raw_payload) = 'object'::text)),
    CONSTRAINT ck_robot_status_history_reason CHECK (((reason_code IS NULL) OR ((reason_code)::text = ANY ((ARRAY['NONE'::character varying, 'REMOTE_PAUSE'::character varying, 'REMOTE_ESTOP'::character varying, 'OBSTACLE'::character varying, 'BOUNDARY_LOST'::character varying, 'LOW_BATTERY'::character varying, 'CRITICAL_BATTERY'::character varying, 'LIDAR_FAULT'::character varying, 'MOTOR_FAULT'::character varying, 'INTERNAL_ERROR'::character varying, 'GRACEFUL_SHUTDOWN'::character varying, 'CRITICAL_BATTERY_SHUTDOWN'::character varying, 'SYSTEM_FAULT_SHUTDOWN'::character varying, 'UNGRACEFUL_DISCONNECT'::character varying, 'HEARTBEAT_TIMEOUT'::character varying, 'REPLACED_BY_NEW_BOOT'::character varying])::text[])))),
    CONSTRAINT ck_robot_status_history_sequence CHECK (((seq IS NULL) OR (seq >= 1))),
    CONSTRAINT ck_robot_status_history_shape CHECK (((((event_kind)::text = ANY ((ARRAY['PRESENCE'::character varying, 'TIMEOUT'::character varying])::text[])) AND (seq IS NULL) AND (connectivity_status IS NOT NULL) AND (robot_mode IS NULL)) OR (((event_kind)::text = 'STATE'::text) AND (seq IS NOT NULL) AND (connectivity_status IS NULL) AND (robot_mode IS NOT NULL))))
);


