--
-- Name: robot_telemetry; Type: TABLE; Schema: telemetry; Owner: gilbom_flyway
--

CREATE TABLE telemetry.robot_telemetry (
    message_id uuid NOT NULL,
    schema_version character varying(10) NOT NULL,
    robot_id uuid NOT NULL,
    boot_id uuid NOT NULL,
    seq bigint NOT NULL,
    sampled_at timestamp with time zone NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    position_valid boolean NOT NULL,
    "position" public.geometry(Point,4326),
    heading_deg double precision,
    moving boolean NOT NULL,
    speed_mps double precision,
    battery_valid boolean NOT NULL,
    battery_percent numeric(5,2),
    battery_state character varying(20) NOT NULL,
    battery_source character varying(20),
    battery_voltage_v double precision,
    battery_current_a double precision,
    charging boolean,
    battery_temperature_c double precision,
    estimated_runtime_sec integer,
    jetson_temp_c double precision,
    mission_state character varying(20),
    mission_elapsed_sec integer,
    mission_incident_count integer,
    raw_payload jsonb NOT NULL,
    mission_id uuid,
    CONSTRAINT ck_robot_telemetry_battery CHECK ((((battery_valid = true) AND (battery_percent IS NOT NULL) AND ((battery_percent >= 0.0) AND (battery_percent <= 100.0)) AND ((battery_state)::text = ANY ((ARRAY['NORMAL'::character varying, 'LOW'::character varying, 'CRITICAL'::character varying])::text[])) AND ((battery_source)::text = ANY ((ARRAY['MEASURED'::character varying, 'ESTIMATED'::character varying])::text[]))) OR ((battery_valid = false) AND (battery_percent IS NULL) AND ((battery_state)::text = 'UNKNOWN'::text) AND (battery_source IS NULL)))),
    CONSTRAINT ck_robot_telemetry_estimated_runtime CHECK (((estimated_runtime_sec IS NULL) OR (estimated_runtime_sec >= 0))),
    CONSTRAINT ck_robot_telemetry_heading CHECK (((heading_deg IS NULL) OR ((heading_deg >= (0.0)::double precision) AND (heading_deg < (360.0)::double precision)))),
    CONSTRAINT ck_robot_telemetry_mission_metrics CHECK ((((mission_elapsed_sec IS NULL) OR (mission_elapsed_sec >= 0)) AND ((mission_incident_count IS NULL) OR (mission_incident_count >= 0)))),
    CONSTRAINT ck_robot_telemetry_mission_state CHECK (((mission_state IS NULL) OR ((mission_state)::text = ANY ((ARRAY['READY'::character varying, 'RUNNING'::character varying, 'PAUSED'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'FAILED'::character varying])::text[])))),
    CONSTRAINT ck_robot_telemetry_position CHECK ((((position_valid = true) AND ("position" IS NOT NULL)) OR ((position_valid = false) AND ("position" IS NULL) AND (heading_deg IS NULL)))),
    CONSTRAINT ck_robot_telemetry_raw_payload CHECK ((jsonb_typeof(raw_payload) = 'object'::text)),
    CONSTRAINT ck_robot_telemetry_schema_version CHECK (((schema_version)::text = '2.0'::text)),
    CONSTRAINT ck_robot_telemetry_seq CHECK ((seq >= 1)),
    CONSTRAINT ck_robot_telemetry_speed CHECK (((speed_mps IS NULL) OR (speed_mps >= (0.0)::double precision)))
);


